# Tables of rubik_solve_asm, generated from the C tables in tables.c.
#
# Entry (state s, face f), f = 0 R, 1 B, 2 D, is the word at s*12 + f*4:
#   bits  0..15  byte offset of the state one quarter turn away, next*12
#   bits 16..23  distance of that state (perm_dist or ori_dist)
#   bits 24..31  0
#
# rubik_near lists the 12,224 states within 5 moves of solved, one word
# each, (p * 3) << 15 | (o * 3) << 3 | distance, for the permutation rank p
# and the orientation rank o. The words sort in the order of the rank
# p * 729 + o, and the key is made from the table offsets (p * 12, o * 12)
# by shifts alone.

